const data = $input.first().json;
const byTier = data.by_tier || {};
const latestImport = data.latest_import_at || data.latest_import || null;
const score = data.avg_final_risk_score ?? data.average_score ?? null;
const dashboardUrl = $env.PFE_DASHBOARD_URL;
const html = `
<h2>Rapport quotidien Bad Debts - SOS Solde & Data</h2>
<p>Bonjour, voici la synthese quotidienne des creances a risque.</p>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:13px;">
  <tr><td><strong>Total clients scores</strong></td><td>${data.total_clients_scored ?? '-'}</td></tr>
  <tr><td><strong>Clients a risque</strong></td><td>${data.at_risk_count ?? '-'}</td></tr>
  <tr><td><strong>Risque eleve</strong></td><td>${byTier.high ?? byTier.High ?? '-'}</td></tr>
  <tr><td><strong>Anomalies</strong></td><td>${data.anomaly_count ?? '-'}</td></tr>
  <tr><td><strong>Score moyen</strong></td><td>${score ?? '-'}</td></tr>
  <tr><td><strong>Dernier import</strong></td><td>${latestImport ?? '-'}</td></tr>
</table>
<p><a href="${dashboardUrl}">Ouvrir le dashboard Bad Debts</a></p>
<p style="color:#666;font-size:12px;">Email interne genere par n8n a partir des APIs FastAPI. LangGraph reste l'orchestrateur agentic.</p>`;
return [{ json: { ...data, html_body: html, subject: 'Rapport quotidien Bad Debts - SOS Solde & Data' } }];
